표 = [("사과", 3, 1000), ("배", 2, 2000)]
def 비싼것(표):
    가장 = ""
    높은 = 0
    for 이름, 개수, 값 in 표:
        if 값 > 높은:
            가장, 높은 = 이름, 값
    return 가장, 높은
이름, 값 = 비싼것(표)
print(f"가장 비싼 것 {이름} {값}원")
